  (match e with Some x => k | None => None end)
  (at level 200, x pattern, e at level 100, k at level 200, only parsing).

Definition g_e (big : list Z) (a r z : Z) : option Z := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S20!1+_V+0!2+_W+0+0$big;R!1+8+0$a;R+0$r;R+0$z;R+0-^NRN$~R+^N0!2'_:#3#12-_VRN$x;R!1+_V10!3'aL'aE!2'^W#4#3!4,_Y+0+0!1,5|32;!2'`2!1,5|31;!2'F#2#32$p;R1-_WRN$p;R!2+_W+0+00#11$i;R+0$e;R+0!2,_Z+0#1!1,^G+0!2,_Z+0,9").
