Definition TS (r0 : Z) (big : list Z) (a z e : Z) : Prop :=
  W9 big /\ zlength big = 128 /\ 0 <= a < z /\ z <= 127 /\ zeros_below big a /\
  (r0 = 0 \/ (r0 = 122 /\ 85 <= a <= 122)) /\
  exists k, 1 <= k <= 9 /\ 10^(k-1) <= znth big a < 10^k /\ e = 9 * (r0 - a) + k - 1.

