Theorem H_spec : forall o p1 prefix pl r0 big a z e,
  TS r0 big a z e -> znth big a <> 0 -> 1 <= p1 <= 26 -> 0 <= pl -> 0 <= prefix -> prefix + pl <= 18 ->
  Forall gch (zsub PREFIX_STR prefix pl) ->
